		c.JSON(http.StatusUnauthorized, gin.H{"error": "Login required"})
		return
	}
	row := db.QueryRow(
		"SELECT id, owner, title, body, COALESCE(escalation_ref, 0) FROM reports WHERE owner = ? ORDER BY id LIMIT 1",
		cl.Username,
